/**
 * Simple slugify function used for marketing content.
 *
 * @param input - Text to slugify
 * @returns Lowercase string with collapsed spaces to single hyphens and
 *          only alphanumeric and hyphen characters.
 */
export function slugify(input: string): string {
  // Trim leading/trailing whitespace and newline characters.
  const trimmed = input.trim();
  // Collapse any internal whitespace (spaces, tabs, newlines) into single hyphens.
  const collapsed = trimmed.replace(/\s+/g, '-');
  // Replace hyphens next to hyphens with single hyphens (edge case handling).
  const normalized = collapsed.replace(/-+/g, '-');
  // Lowercase everything and strip characters outside of [a-z0-9-].
  return normalized.toLowerCase().replace(/[^a-z0-9-]/g, '');
}

import { test, describe } from 'node:test';
import assert from 'node:assert';
import { slugify } from './slugify';

describe('slugify', () => {
  test('"Hello World" → "hello-world"', () => {
    assert.strictEqual(slugify('Hello World'), 'hello-world');
  });

  test('leading and trailing whitespace are trimmed', () => {
    assert.strictEqual(slugify('  Foo Bar  '), 'foo-bar');
  });

  test('punctuation is stripped, multiple spaces collapse to single hyphens', () => {
    assert.strictEqual(slugify('Foo Bar!'), 'foo-bar');
  });
});

