const fs = require('fs');
const path = require('path');

const slugify = (input) => {
  return input
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-')       // collapse whitespace to single hyphens
    .replace(/[^a-z0-9-]/g, '') // strip characters outside [a-z0-9-]
    .replace(/-+/g, '-')        // collapse multiple hyphens
    .replace(/^-|-$/g, '');      // strip leading/trailing hyphens
};

const code = `
import { test, describe } from 'node:test';
import assert from 'node:assert';
import { slugify } from './slugify.js';

describe('slugify', () => {
  test('"Hello World" → "hello-world"', () => {
    assert.strictEqual(slugify('Hello World'), 'hello-world');
  });

  test('leading and trailing whitespace are trimmed', () => {
    assert.strictEqual(slugify('  Foo Bar  '), 'foo-bar');
  });

  test('punctuation is stripped, multiple spaces collapse to single hyphens', () => {
    assert.strictEqual(slugify('Foo Bar!'), 'foo-bar');
  });
});
`;

fs.writeFileSync('marketing-capture/readme_test_note.txt', code);
console.log('node:test script written to marketing-capture/readme_test_note.txt');
console.log('Expected result: slugify("Foo Bar!") → "foo-bar"');

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// Ensure .js build dir exists
const buildDir = 'marketing-capture/.js';
if (!fs.existsSync(buildDir)) {
  fs.mkdirSync(buildDir, { recursive: true });
}

// Copy/symlink sources to .js for clean transpilation ordering
const srcSlug = path.join(__dirname, 'marketing-capture/slugify.ts');
const dstSlug = path.join(buildDir, 'slugify.js');

// Simple Node-based transpilation (replace ESM imports with require for .js compatibility)
const tsCode = fs.readFileSync(srcSlug, 'utf-8');
const esmCode = tsCode
  .replace("export function slugify", "function slugify")
  .replace("node:test", "node:test")
  .replace("./slugify.js", "./slugify.js"); // keep import as is

fs.writeFileSync(dstSlug, esmCode);
console.log(`Wrote compiled slugify.js to ${dstSlug}`);

const execSync = require('child_process').execSync;
const fs = require('fs');
const path = require('path');

// Build dir for compiled .js versions to support running on Node's test runner
const buildDir = 'marketing-capture/.js';
if (!fs.existsSync(buildDir)) {
  fs.mkdirSync(buildDir, { recursive: true });
}

// Copy slugify.ts to slugify.js and adapt to CJS temporarily for the demo (avoid further transpile if not needed)
const srcSlug = path.join(__dirname, 'marketing-capture/slugify.ts');
const dstSlug = path.join(buildDir, 'slugify.js');

// source TS already matches what slugify.test.ts imports; just copy
fs.copyFileSync(srcSlug, dstSlug);
console.log(`Copied slugify.ts → slugify.js in ${dstSlug}`);

// Run node --test on the .js version
try {
  execSync('node --test marketing-capture/.js', { stdio: 'inherit', cwd: path.join(__dirname, 'marketing-capture') });
  console.log('\nTests passed! Example: slugify("Foo Bar!") → "foo-bar"');
} catch (err) {
  console.error('Tests failed:', err.message);
  throw err;
}
